candidates.raw:
int i, j;
int isolated_count = 0;
int outlier_count = 0;
adcs_vec3_t raw[3];
adcs_vec3_t median;
double d2[3];

gv_output.mode = GV_FAULT;
gv_output.voted_rate_rad_s.x = 0.0;
gv_output.voted_rate_rad_s.y = 0.0;
gv_output.voted_rate_rad_s.z = 0.0;
gv_output.distance_rad_s[0] = 0.0;
gv_output.distance_rad_s[1] = 0.0;
gv_output.distance_rad_s[2] = 0.0;
gv_output.outlier_mask = 0U;

if ((gv_input.enable != 0) && (gv_input.enable != 1)) {
    return;
}
if (gv_input.enable == 0) {
    gv_state.mode = GV_OFF;
    gv_state.bad_streak[0] = 0U;
    gv_state.bad_streak[1] = 0U;
    gv_state.bad_streak[2] = 0U;
    gv_state.good_streak[0] = 0U;
    gv_state.good_streak[1] = 0U;
    gv_state.good_streak[2] = 0U;
    gv_state.isolated[0] = 0;
    gv_state.isolated[1] = 0;
    gv_state.isolated[2] = 0;
    gv_output.mode = GV_OFF;
    return;
}
if ((gv_input.gyro[0] == NULL) || (gv_input.gyro[1] == NULL) ||
    (gv_input.gyro[2] == NULL)) {
    gv_output.mode = GV_FAULT;
    return;
}
if ((!adcs_is_finite_vec3(gv_input.gyro[0])) ||
    (!adcs_is_finite_vec3(gv_input.gyro[1])) ||
    (!adcs_is_finite_vec3(gv_input.gyro[2]))) {
    gv_output.mode = GV_FAULT;
    return;
}
if ((!isfinite(gv_config.threshold_rad_s)) ||
    (!isfinite(gv_config.reentry_threshold_rad_s)) ||
    (gv_config.threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s) ||
    (gv_config.isolate_confirm < 1U) || (gv_config.isolate_confirm > 20U) ||
    (gv_config.reentry_confirm < 1U) || (gv_config.reentry_confirm > 20U)) {
    gv_output.mode = GV_FAULT;
    return;
}

raw[0] = gv_input.gyro[0]->value;
raw[1] = gv_input.gyro[1]->value;
raw[2] = gv_input.gyro[2]->value;

{
    double x[3], y[3], z[3], t;
    x[0] = raw[0].x; x[1] = raw[1].x; x[2] = raw[2].x;
    y[0] = raw[0].y; y[1] = raw[1].y; y[2] = raw[2].y;
    z[0] = raw[0].z; z[1] = raw[1].z; z[2] = raw[2].z;
    for (i = 0; i < 2; i++)
        for (j = 0; j < 2 - i; j++) {
            if (x[j] > x[j + 1]) { t = x[j]; x[j] = x[j + 1]; x[j + 1] = t; }
            if (y[j] > y[j + 1]) { t = y[j]; y[j] = y[j + 1]; y[j + 1] = t; }
            if (z[j] > z[j + 1]) { t = z[j]; z[j] = z[j + 1]; z[j + 1] = t; }
        }
    median.x = x[1];
    median.y = y[1];
    median.z = z[1];
}

for (i = 0; i < 3; i++) {
    double dx = raw[i].x - median.x;
    double dy = raw[i].y - median.y;
    double dz = raw[i].z - median.z;
    d2[i] = sqrt(dx * dx + dy * dy + dz * dz);
    gv_output.distance_rad_s[i] = d2[i];
}
gv_output.outlier_mask = 0U;
for (i = 0; i < 3; i++) {
    if (d2[i] > gv_config.threshold_rad_s) {
        gv_output.outlier_mask |= (unint32)(1U << i);
    }
}

for (i = 0; i < 3; i++) {
    if (!gv_state.isolated[i]) {
        if (d2[i] > gv_config.threshold_rad_s) {
            gv_state.bad_streak[i] += 1U;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
            }
        } else {
            gv_state.bad_streak[i] = 0U;
        }
    } else {
        if (d2[i] <= gv_config.reentry_threshold_rad_s) {
            gv_state.good_streak[i] += 1U;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.good_streak[i] = 0U;
        }
    }
}

isolated_count = 0;
for (i = 0; i < 3; i++)
    if (gv_state.isolated[i]) isolated_count++;

outlier_count = 0;
for (i = 0; i < 3; i++)
    if (d2[i] > gv_config.threshold_rad_s) outlier_count++;

if (isolated_count == 0) {
    if (outlier_count == 0) {
        gv_output.mode = GV_NOMINAL;
        gv_output.voted_rate_rad_s = median;
    } else if (outlier_count == 1) {
        int a = -1, b = -1;
        for (i = 0; i < 3; i++) {
            if (d2[i] <= gv_config.threshold_rad_s) {
                if (a < 0) a = i;
                else b = i;
            }
        }
        if ((a >= 0) && (b >= 0)) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s.x = 0.5 * (raw[a].x + raw[b].x);
            gv_output.voted_rate_rad_s.y = 0.5 * (raw[a].y + raw[b].y);
            gv_output.voted_rate_rad_s.z = 0.5 * (raw[a].z + raw[b].z);
        } else {
            gv_output.mode = GV_FAULT;
        }
    } else {
        gv_output.mode = GV_FAULT;
    }
} else if (isolated_count == 1) {
    int a = -1, b = -1;
    for (i = 0; i < 3; i++) {
        if (!gv_state.isolated[i]) {
            if (a < 0) a = i;
            else b = i;
        }
    }
    if ((a >= 0) && (b >= 0)) {
        double dx = raw[a].x - raw[b].x;
        double dy = raw[a].y - raw[b].y;
        double dz = raw[a].z - raw[b].z;
        double dist = sqrt(dx * dx + dy * dy + dz * dz);
        if (dist <= gv_config.threshold_rad_s) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s.x = 0.5 * (raw[a].x + raw[b].x);
            gv_output.voted_rate_rad_s.y = 0.5 * (raw[a].y + raw[b].y);
            gv_output.voted_rate_rad_s.z = 0.5 * (raw[a].z + raw[b].z);
        } else {
            gv_output.mode = GV_FAULT;
        }
    } else {
        gv_output.mode = GV_FAULT;
    }
} else {
    gv_output.mode = GV_FAULT;
}

gv_state.mode = gv_output.mode;

