candidates.raw:
unint32 i;
unint32 k;
int valid = 1;
unint32 outlier_count = 0U;
unint32 isolated_count = 0U;
adcs_vec3_t s[3];
adcs_vec3_t median;
double d[3];
adcs_vec3_t sum;
int remaining[3];
unint32 remaining_count;

/* Parameter validation */
if ((gv_input.enable != 0) && (gv_input.enable != 1))
    valid = 0;
if (!isfinite(gv_config.threshold_rad_s) || (gv_config.threshold_rad_s < 0.0))
    valid = 0;
if (!isfinite(gv_config.reentry_threshold_rad_s) || (gv_config.reentry_threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s))
    valid = 0;
if ((gv_config.isolate_confirm < 1U) || (gv_config.isolate_confirm > 20U))
    valid = 0;
if ((gv_config.reentry_confirm < 1U) || (gv_config.reentry_confirm > 20U))
    valid = 0;
for (i = 0U; i < 3U; i++) {
    if (gv_input.gyro[i] == NULL)
        valid = 0;
    else if (!adcs_is_finite_vec3(gv_input.gyro[i]))
        valid = 0;
}

if (gv_input.enable != 1) {
    gv_state.bad_streak[0] = 0U;
    gv_state.bad_streak[1] = 0U;
    gv_state.bad_streak[2] = 0U;
    gv_state.good_streak[0] = 0U;
    gv_state.good_streak[1] = 0U;
    gv_state.good_streak[2] = 0U;
    gv_state.isolated[0] = 0;
    gv_state.isolated[1] = 0;
    gv_state.isolated[2] = 0;
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gv_output.mode = GV_OFF;
    gv_state.mode = GV_OFF;
    return;
}

if (!valid) {
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    gv_output.mode = GV_FAULT;
    gv_state.mode = GV_FAULT;
    return;
}

for (i = 0U; i < 3U; i++)
    s[i] = gv_input.gyro[i]->value;

/* Component-wise median of all three raw sensors */
for (k = 0U; k < 3U; k++) {
    double v0, v1, v2, mid;
    if (k == 0U) { v0 = s[0].x; v1 = s[1].x; v2 = s[2].x; }
    else if (k == 1U) { v0 = s[0].y; v1 = s[1].y; v2 = s[2].y; }
    else { v0 = s[0].z; v1 = s[1].z; v2 = s[2].z; }
    if ((v0 <= v1 && v1 <= v2) || (v2 <= v1 && v1 <= v0))
        mid = v1;
    else if ((v1 <= v0 && v0 <= v2) || (v2 <= v0 && v0 <= v1))
        mid = v0;
    else
        mid = v2;
    if (k == 0U) median.x = mid;
    else if (k == 1U) median.y = mid;
    else median.z = mid;
}

/* Euclidean distance of each sensor from median */
for (i = 0U; i < 3U; i++) {
    double dx = s[i].x - median.x;
    double dy = s[i].y - median.y;
    double dz = s[i].z - median.z;
    d[i] = sqrt(dx * dx + dy * dy + dz * dz);
}

/* Per-cycle outlier mask: strictly greater than threshold */
gv_output.outlier_mask = 0U;
outlier_count = 0U;
for (i = 0U; i < 3U; i++) {
    gv_output.distance_rad_s[i] = d[i];
    if (d[i] > gv_config.threshold_rad_s) {
        gv_output.outlier_mask |= (unint32)(1U << i);
        outlier_count++;
    }
}

/* Streak updates */
for (i = 0U; i < 3U; i++) {
    int is_outlier = (gv_output.outlier_mask & (unint32)(1U << i)) ? 1 : 0;
    if (!gv_state.isolated[i]) {
        if (is_outlier) {
            gv_state.bad_streak[i]++;
        } else {
            gv_state.bad_streak[i] = 0U;
        }
        if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
            gv_state.isolated[i] = 1;
            gv_state.bad_streak[i] = 0U;
            gv_state.good_streak[i] = 0U;
        }
    } else {
        int agrees = (!is_outlier) && (d[i] <= gv_config.reentry_threshold_rad_s);
        if (agrees)
            gv_state.good_streak[i]++;
        else
            gv_state.good_streak[i] = 0U;
        if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
            gv_state.isolated[i] = 0;
            gv_state.bad_streak[i] = 0U;
            gv_state.good_streak[i] = 0U;
        }
    }
}

/* Count isolated after this cycle's streak updates */
isolated_count = 0U;
for (i = 0U; i < 3U; i++) {
    if (gv_state.isolated[i])
        isolated_count++;
}

/* Voter table */
if (isolated_count == 0U) {
    if (outlier_count == 0U) {
        gv_output.mode = GV_NOMINAL;
        gv_output.voted_rate_rad_s = median;
    } else if (outlier_count == 1U) {
        sum = (adcs_vec3_t){0.0, 0.0, 0.0};
        remaining_count = 0U;
        for (i = 0U; i < 3U; i++) {
            if (!(gv_output.outlier_mask & (unint32)(1U << i))) {
                remaining_count++;
                sum.x += s[i].x;
                sum.y += s[i].y;
                sum.z += s[i].z;
            }
        }
        if (remaining_count == 2U) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){sum.x / 2.0, sum.y / 2.0, sum.z / 2.0};
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else if (isolated_count == 1U) {
    remaining_count = 0U;
    for (i = 0U; i < 3U; i++) {
        if (!gv_state.isolated[i]) {
            remaining[remaining_count] = (int)i;
            remaining_count++;
        }
    }
    if (remaining_count == 2U) {
        adcs_vec3_t a = s[remaining[0]];
        adcs_vec3_t b = s[remaining[1]];
        double ddx = b.x - a.x;
        double ddy = b.y - a.y;
        double ddz = b.z - a.z;
        double mutual = sqrt(ddx * ddx + ddy * ddy + ddz * ddz);
        if (mutual <= gv_config.threshold_rad_s) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s =
                (adcs_vec3_t){(a.x + b.x) / 2.0, (a.y + b.y) / 2.0, (a.z + b.z) / 2.0};
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}

gv_state.mode = gv_output.mode;

