/* Streak updates */
for (i = 0U; i < 3U; i++) {
    int is_outlier = (gv_output.outlier_mask & (uint32_t)(1U << i)) ? 1 : 0;
    if (!gv_state.isolated[i]) {
        if (is_outlier) {
            gv_state.bad_streak[i]++;
        } else {
            gv_state.bad_streak[i] = 0U;
        }
        if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
            gv_state.isolated[i] = 1;
            gv_state.bad_streak[i] = 0U;
            gv_state.good_streak[i] = 0U;
        }
    } else {
        int agrees = ((!is_outlier) && (d[i] <= gv_config.reentry_threshold_rad_s)) ? 1 : 0;
        if (agrees)
            gv_state.good_streak[i]++;
        else
            gv_state.good_streak[i] = 0U;
        if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
            gv_state.isolated[i] = 0;
            gv_state.bad_streak[i] = 0U;
            gv_state.good_streak[i] = 0U;
        }
    }
}

/* Count isolated after this cycle's streak updates */
isolated_count = 0U;
for (i = 0U; i < 3U; i++) {
    if (gv_state.isolated[i])
        isolated_count++;
}

/* Voter table */
if (isolated_count == 0U) {
    if (outlier_count == 0U) {
        gv_output.mode = GV_NOMINAL;
        gv_output.voted_rate_rad_s = median;
    } else if (outlier_count == 1U) {
        sum = (adcs_vec3_t){0.0, 0.0, 0.0};
        remaining_count = 0U;
        for (i = 0U; i < 3U; i++) {
            if (!(gv_output.outlier_mask & (uint32_t)(1U << i))) {
                remaining_count++;
                sum.x += s[i].x;
                sum.y += s[i].y;
                sum.z += s[i].z;
            }
        }
        if (remaining_count == 2U) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){sum.x / 2.0, sum.y / 2.0, sum.z / 2.0};
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else if (isolated_count == 1U) {
    remaining_count = 0U;
    for (i = 0U; i < 3U; i++) {
        if (!gv_state.isolated[i]) {
            remaining[remaining_count] = i;
            remaining_count++;
        }
    }
    if (remaining_count == 2U) {
        adcs_vec3_t a = s[remaining[0]];
        adcs_vec3_t b = s[remaining[1]];
        double ddx = b.x - a.x;
        double ddy = b.y - a.y;
        double ddz = b.z - a.z;
        double mutual = sqrt(ddx * ddx + ddy * ddy + ddz * ddz);
        if (mutual <= gv_config.threshold_rad_s) {
            gv_output.mode = GV_DEGRADED;
            gv_output.voted_rate_rad_s =
                (adcs_vec3_t){(a.x + b.x) / 2.0, (a.y + b.y) / 2.0, (a.z + b.z) / 2.0};
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
} else {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}

gv_state.mode = gv_output.mode;
